    <input type="text"
           placeholder="Search tasks by title…"
           value="@SearchText"
           @oninput="HandleInput" />
</div>

@code {
    [Parameter]
    public string SearchText { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public EventCallback<string> OnSearchChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        await OnSearchChanged.InvokeAsync(e.Value?.ToString() ?? string.Empty);
    }
}
"}

{"path": "/tmp/sv-39e9f3de9e2143818112349870eb4f57/Components/Pages/Board/BoardColumn.razor", "file_text": "<div class="board-column">
    <div class="column-header">
        <h3>@ColumnName</h3>
        <span class="column-count">@Tasks.Count</span>
    </div>

    <div class="column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      ShowMoveLeft="ShowMoveLeft"
                      ShowMoveRight="ShowMoveRight"
                      OnMoveLeft="() => OnMoveTask.InvokeAsync((task.Id, -1))"
                      OnMoveRight="() => OnMoveTask.InvokeAsync((task.Id, 1))" />
        }
    </div>

    <AddTaskForm Status="@ColumnStatus" OnTaskCreated="OnTaskCreated" />
</div>

@code {
    [Parameter, EditorRequired]
    public string ColumnName { get; set; } = default!;

    [Parameter, EditorRequired]
    public string ColumnStatus { get; set; } = default!;

    [Parameter, EditorRequired]
    public List<TaskItem> Tasks { get; set; } = new();

    [Parameter]
    public bool ShowMoveLeft { get; set; }

    [Parameter]
    public bool ShowMoveRight { get; set; }

    /// <summary>Carries (taskId, direction) where direction is -1 (left) or +1 (right).</summary>
    [Parameter, EditorRequired]
    public EventCallback<(int TaskId, int Direction)> OnMoveTask { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<TaskItem> OnTaskCreated { get; set; }
}
"}

